import{_ as a,c as t,o as s,ak as i,aq as r}from"./chunks/framework.DHLlVITf.js";const p=JSON.parse('{"title":"AireFrame Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/aireframe-v3-2-0.md","filePath":"aireblock-releases/aireframe-v3-2-0.md","lastUpdated":1785933784000}'),o={name:"aireblock-releases/aireframe-v3-2-0.md"};function n(c,e,l,d,h,m){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="aireframe-release-notes" tabindex="-1"><span class="fsc-product"><img src="'+r+'"> AireFrame Release Notes</span> <a class="header-anchor" href="#aireframe-release-notes" aria-label="Permalink to “AireFrame Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 3.2.0<br><strong>Release Date:</strong> 12 August 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Customisable PDF Headers (FRAME-2613)</li><li>Smarter Subject Search (FRAME-2618)</li><li>Widget Updates on Location Changes (FRAME-2627)</li></ul><h4 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h4><ul><li>AI Guardrails for Data Summaries (FRAME-2658)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Improved Session Token Security (FRAME-2536)</li><li>Cleaner AI Widget Output (FRAME-2581)</li><li>Fixed Data Extract Update Conflicts (FRAME-2656)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="customisable-pdf-headers-frame-2613" tabindex="-1">Customisable PDF Headers (FRAME-2613) <a class="header-anchor" href="#customisable-pdf-headers-frame-2613" aria-label="Permalink to “Customisable PDF Headers (FRAME-2613)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>System admins can now design a custom HTML header for AireForms PDFs, with access to subject field data and basic HTML formatting such as bold and italics.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now personalise the headers on your generated PDFs, including your organisation&#39;s own fields and simple formatting.</p></div><h4 id="smarter-subject-search-frame-2618" tabindex="-1">Smarter Subject Search (FRAME-2618) <a class="header-anchor" href="#smarter-subject-search-frame-2618" aria-label="Permalink to “Smarter Subject Search (FRAME-2618)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Subject search results now display exact matches ahead of fuzzy matches in a separate section, with a clear indicator showing whether each result is an exact or fuzzy match.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Finding the right subject is faster and clearer, as you can immediately see which results are exact matches and which are close matches worth double-checking.</p></div><h4 id="widget-updates-on-location-changes-frame-2627" tabindex="-1">Widget Updates on Location Changes (FRAME-2627) <a class="header-anchor" href="#widget-updates-on-location-changes-frame-2627" aria-label="Permalink to “Widget Updates on Location Changes (FRAME-2627)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Widget data will still appear when a subject is added or removed from a location, without needing to wait for the new widget data to be generated. This ensures that data is always displayed when a subject&#39;s location changes, even if the widget data is still being processed.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Your widgets will now display data more reliably when subjects are moved between locations, improving the user experience.</p></div><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><hr><h4 id="ai-guardrails-for-data-summaries-frame-2658" tabindex="-1">AI Guardrails for Data Summaries (FRAME-2658) <a class="header-anchor" href="#ai-guardrails-for-data-summaries-frame-2658" aria-label="Permalink to “AI Guardrails for Data Summaries (FRAME-2658)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The Data Summary Agent now supports AWS Guardrails, adding an additional layer of content safety controls to AI-generated summaries.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>AI-generated data summaries are now subject to extra safety checks, giving you added confidence in the content you&#39;re presented with.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="improved-session-token-security-frame-2536" tabindex="-1">Improved Session Token Security (FRAME-2536) <a class="header-anchor" href="#improved-session-token-security-frame-2536" aria-label="Permalink to “Improved Session Token Security (FRAME-2536)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The authentication flow has been updated to use <code>response_mode=form_post</code> instead of passing the session token via the URL, reducing the risk of token exposure.</p></div><h4 id="cleaner-ai-widget-output-frame-2581" tabindex="-1">Cleaner AI Widget Output (FRAME-2581) <a class="header-anchor" href="#cleaner-ai-widget-output-frame-2581" aria-label="Permalink to “Cleaner AI Widget Output (FRAME-2581)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where AI Widgets occasionally displayed a stray <code>&lt;hr /&gt;</code> tag in generated content, caused by markdown <code>---</code> being translated into HTML. The <code>hr</code> tag has been added to the frontend&#39;s HTML whitelist to render it correctly.</p></div><h4 id="fixed-data-extract-update-conflicts-frame-2656" tabindex="-1">Fixed Data Extract Update Conflicts (FRAME-2656) <a class="header-anchor" href="#fixed-data-extract-update-conflicts-frame-2656" aria-label="Permalink to “Fixed Data Extract Update Conflicts (FRAME-2656)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where data could be displayed incorrectly when multiple notifications arrived for the same subject and data extract at the same time.</p></div>',34)])])}const f=a(o,[["render",n]]);export{p as __pageData,f as default};
